    -- Key check function
    local function checkKeyWithRetry(key, retryCount)
        if not key or key == "" then return nil, "No key provided" end
        
        retryCount = retryCount or 0
        local currentTime = tick()
        local timeSinceLast = currentTime - lastRequestTime
        
        if timeSinceLast < MIN_REQUEST_INTERVAL then
            task.wait(MIN_REQUEST_INTERVAL - timeSinceLast)
        end
        
        lastRequestTime = tick()
        
        local success, result = pcall(function()
            return Junkie.check_key(key)
        end)
        
        if success and result then
            return result
        end
        
        if AUTO_RETRY_ENABLED and retryCount < MAX_RETRY_ATTEMPTS then
            task.wait(RETRY_DELAY)
            return checkKeyWithRetry(key, retryCount + 1)
        end
        
        return nil, "Check failed after " .. (retryCount + 1) .. " attempts"
    end
    
    -- File system functions
    local function hasFileSystemSupport()
        local hasWritefile = pcall(function() return type(writefile) == "function" end)
        local hasReadfile = pcall(function() return type(readfile) == "function" end)
        local hasIsfile = pcall(function() return type(isfile) == "function" end)
        return hasWritefile and hasReadfile and hasIsfile
    end
    
    local fileSystemSupported = hasFileSystemSupport()
    
    local function getKeyFileName()
        if currentPlayerUserId > 0 then
            return "junkie_key_" .. tostring(currentPlayerUserId) .. ".json"
        else
            return "junkie_key_" .. string.gsub(currentPlayerName, "[^%w]", "_") .. ".json"
        end
    end
    
    local function saveKey(key)
        if not fileSystemSupported then return false end
        
        local saveData = {
            key = key,
            username = currentPlayerName,
            userId = currentPlayerUserId,
            timestamp = os.time(),
            version = "1.4",
            lastVerified = os.time()
        }
        
        local fileName = getKeyFileName()
        local ok = pcall(function()
            local jsonData = HttpService:JSONEncode(saveData)
            writefile(fileName, jsonData)
        end)
        return ok
    end
    
    local function loadKey()
        if not fileSystemSupported then 
            return nil, nil, nil
        end
        
        local fileName = getKeyFileName()
        local ok, content = pcall(function()
            if not isfile(fileName) then
                return nil
            end
            return readfile(fileName)
        end)
        
        if not ok or not content then 
            return nil, nil, nil
        end
        
        local success, data = pcall(function()
            return HttpService:JSONDecode(content)
        end)
        
        if success and data and data.key and data.username then
            if data.lastVerified and (os.time() - data.lastVerified) > (7 * 24 * 60 * 60) then
                return nil, nil, nil
            end
            return data.key, data.username, data.userId
        end
        
        return nil, nil, nil
    end
    
    local function clearKey()
        if not fileSystemSupported then return false end
        local fileName = getKeyFileName()
        local ok = pcall(function() 
            if isfile(fileName) then
                delfile(fileName)
            end
        end)
        return ok
    end

    -- Particle System
    local ParticleSystem = {}
    ParticleSystem.__index = ParticleSystem
    
    function ParticleSystem.new(parent)
        local self = setmetatable({}, ParticleSystem)
        self.container = Instance.new("Frame")
        self.container.Name = "ParticleContainer"
        self.container.Size = UDim2.new(1, 0, 1, 0)
        self.container.BackgroundTransparency = 1
        self.container.ClipsDescendants = true
        self.container.Parent = parent
        self.particles = {}
        return self
    end
    
    function ParticleSystem:emit(position, colorSequence, count, speed, size, lifetime)
        for i = 1, count do
            local particle = Instance.new("Frame")
            particle.Name = "Particle"
            particle.Size = UDim2.new(0, size or 4, 0, size or 4)
            particle.Position = UDim2.new(0, position.X.Offset, 0, position.Y.Offset)
            particle.AnchorPoint = Vector2.new(0.5, 0.5)
            particle.BackgroundColor3 = colorSequence.Keypoints[1].Value
            particle.BorderSizePixel = 0
            
            local corner = Instance.new("UICorner")
            corner.CornerRadius = UDim.new(1, 0)
            corner.Parent = particle
            
            particle.Parent = self.container
            
            local angle = math.random() * math.pi * 2
            local distance = math.random(20, 80)
            local targetX = position.X.Offset + math.cos(angle) * distance
            local targetY = position.Y.Offset + math.sin(angle) * distance
            
            local tweenInfo = TweenInfo.new(
                lifetime or 0.8,
                Enum.EasingStyle.Quad,
                Enum.EasingDirection.Out
            )
            
            local tween = TweenService:Create(particle, tweenInfo, {
                Position = UDim2.new(0, targetX, 0, targetY),
                BackgroundTransparency = 1,
                Size = UDim2.new(0, 0, 0, 0)
            })
            
            tween:Play()
            tween.Completed:Connect(function()
                particle:Destroy()
            end)
            
            table.insert(self.particles, particle)
        end
    end
    
    function ParticleSystem:createButtonParticles(button)
        local connection
        connection = button.MouseButton1Click:Connect(function()
            local absolutePosition = button.AbsolutePosition
            local absoluteSize = button.AbsoluteSize
            local centerX = absolutePosition.x + absoluteSize.x / 2
            local centerY = absolutePosition.y + absoluteSize.y / 2
            
            local colorSeq = ParticleColors.primary
            if button.Name:find("Verify") then
                colorSeq = ParticleColors.success
            elseif button.Name:find("Close") then
                colorSeq = ParticleColors.error
            end
            
            self:emit(
                UDim2.new(0, centerX, 0, centerY),
                colorSeq,
                8,
                1,
                6,
                0.6
            )
        end)
        
        return connection
    end
    
